def run(core,checker):
    core=Path(core).resolve()
    if not PC.static_registration(core):return None
    archive=ROOT/'docs/research/static-provider-dispatch/controls'
    cases=[]
    with tempfile.TemporaryDirectory(prefix='bendvy-static-boundary-') as temporary:
        for name,contract in sorted(CASES.items()):
            original=archive/(name+'.bend.txt');text=original.read_text()
            assert PC.sha(original)==contract['sourceSHA256'],'Static control archive drift: '+name
            imports=re.findall(r'^import (\S+)',text,re.M)
            for relative in imports:
                if relative=='Base':continue
                assert relative.startswith('../JS/experiments/s-integrate/') and relative.endswith('.bend'),'Unexpected control import'
                target=core/Path(relative).name
                assert target.is_file() and not target.is_symlink(),'Missing actual provider boundary import'
                text=text.replace('import '+relative+' as ','import '+str(target)+' as ')
            source=Path(temporary)/(name+'.bend');source.write_text(text)
            result=checker(source)
            assert result['exit']==contract['exit'],result
            marker='ALL PROOFS CHECK' if contract['exit']==0 else 'SOME PROOFS FAIL'
            assert marker in result['output'],result
            for diagnostic in contract['diagnostics']:assert diagnostic in result['output'],result
            cases.append(dict(name=name,sourceSHA256=PC.sha(source),archiveSHA256=contract['sourceSHA256'],**result))
    assert len(cases)==8 and sum(c['exit']==0 for c in cases)==2
    return {'status':'FRESH_ACTUAL_STATIC_PROVIDER_BOUNDARY_PASS','staticClientSHA256':PC.sha(core/PC.STATIC_MODULE),'heldAdapterSHA256':PC.sha(core/'held-adapter.bend'),'cases':cases}
